#include <WiFi.h>
#include <WebServer.h>
WebServer server(80);
bool on = false;
unsigned long renewedAt = 0;
void setup() {
  Serial.begin(115200); pinMode(18, OUTPUT);
  WiFi.softAP("VoltQuest-Control");
  server.on("/on", []() { on = true; renewedAt = millis(); digitalWrite(18, HIGH); server.send(200, "text/plain", "ON"); });
  server.on("/off", []() { on = false; digitalWrite(18, LOW); server.send(200, "text/plain", "OFF"); });
  server.on("/status", []() { server.send(200, "text/plain", on ? "ON" : "OFF"); });
  server.begin();
}
void loop() {
  if (on && millis() - renewedAt >= 750) { on = false; digitalWrite(18, LOW); Serial.println("EXPIRED"); }
  server.handleClient();
}
